/** Conservative structural diff for rendered browser evidence. Never mutates Elementor. */
class Design_Core_Elementor_Structural_Diff_Engine{const VERSION=1;public function compare(array $reference,array $candidate){$r=$this->states($reference);$c=$this->states($candidate);$views=array_values(array_unique(array_merge(array_keys($r),array_keys($c))));sort($views);$issues=array();$penalty=0;foreach($views as $v){$a=(array)($r[$v]??array());$b=(array)($c[$v]??array());$ac=count($a);$bc=count($b);$ratio=max($ac,$bc)?abs($ac-$bc)/max($ac,$bc):0;if($ratio>.12){$sev=$ratio>.3?'high':'medium';$issues[]=array('viewport'=>(int)$v,'category'=>'element-count','severity'=>$sev,'reference'=>$ac,'candidate'=>$bc,'ratio'=>round($ratio,3));$penalty+=$sev==='high'?22:10;}$as=$this->sections($a);$bs=$this->sections($b);if($as!==$bs){$issues[]=array('viewport'=>(int)$v,'category'=>'section-order','severity'=>'high','reference'=>$as,'candidate'=>$bs);$penalty+=24;}$ah=$this->height($a);$bh=$this->height($b);if($ah>0&&$bh>0){$hr=abs($ah-$bh)/max($ah,$bh);if($hr>.1){$sev=$hr>.25?'high':'medium';$issues[]=array('viewport'=>(int)$v,'category'=>'document-height','severity'=>$sev,'reference'=>$ah,'candidate'=>$bh,'ratio'=>round($hr,3));$penalty+=$sev==='high'?16:7;}}if($this->layout($a)!==$this->layout($b)){$issues[]=array('viewport'=>(int)$v,'category'=>'layout-pattern','severity'=>'medium');$penalty+=6;}}$score=max(0,100-min(100,$penalty/max(1,count($views))));$high=count(array_filter($issues,static fn($i)=>'high'===($i['severity']??'')));$rebuild=$high>0||$score<85;return array('version'=>1,'status'=>$rebuild?'needs-rebuild':($issues?'warning':'pass'),'score'=>round($score,2),'issues'=>$issues,'requires_rebuild'=>$rebuild,'recommended_action'=>$rebuild?'regenerate-affected-section-through-build-plan':'continue-with-control-level-correction','mutation'=>false);}
private function states($x){$o=array();foreach((array)($x['viewports']??$x['results']??array()) as $k=>$s){$v=(int)(is_array($s)?($s['viewport']??$s['width']??$k):$k);if($v>0)$o[$v]=array_values(array_filter((array)($s['elements']??$s['nodes']??array()),'is_array'));}return $o;}private function sections($e){$o=array();foreach($e as $x){$m=(array)($x['elementor']??$x['meta']??array());$t=(string)($m['element_type']??$x['element_type']??'');$tag=strtolower((string)($x['tag']??$x['nodeName']??''));$role=sanitize_key((string)($x['role']??$x['semantic_role']??''));if(in_array($t,array('section','container'),true)||in_array($tag,array('section','header','main','footer','nav'),true))$o[]=$role?:($tag?:$t);}return array_slice($o,0,80);}private function height($e){$m=0;foreach($e as $x){$r=(array)($x['rect']??array());$m=max($m,(float)($r['y']??0)+(float)($r['height']??0));}return round($m,2);}private function layout($e){$c=array('row'=>0,'column'=>0,'grid'=>0,'absolute'=>0);foreach($e as $x){$s=(array)($x['styles']??array());$d=strtolower((string)($s['display']??''));$f=strtolower((string)($s['flexDirection']??''));$p=strtolower((string)($s['position']??''));if('grid'===$d)$c['grid']++;if('flex'===$d&&'column'===$f)$c['column']++;if('flex'===$d&&'column'!==$f)$c['row']++;if(in_array($p,array('absolute','fixed'),true))$c['absolute']++;}return $c;}}
